fn show_provider(&mut self, ui: &mut egui::Ui) {
    ui.heading("Run");
    let run_active = self.active_run_id.as_ref().is_some_and(|run_id| {
        self.host.run(run_id).is_ok_and(|run| {
            !matches!(
                run.state,
                AgentRunState::Completed | AgentRunState::Failed | AgentRunState::Cancelled
            )
        })
    });
    let previous_provider = self.provider_kind;
    ui.add_enabled_ui(!run_active, |ui| {
        ui.horizontal(|ui| {
            ui.label("AgentRuntime");
            egui::ComboBox::from_id_salt("ai_studio_agent_runtime_provider")
                .selected_text(
                    self.provider_kind
                        .map(ExternalAgentProviderKind::label)
                        .unwrap_or("Native local model"),
                )
                .show_ui(ui, |ui| {
                    ui.selectable_value(
                        &mut self.provider_kind,
                        None,
                        "Native local model",
                    );
                    for provider in ExternalAgentProviderKind::ALL {
                        ui.selectable_value(
                            &mut self.provider_kind,
                            Some(provider),
                            provider.label(),
                        );
                    }
                });
        });
        if let Some(provider) = self.provider_kind {
            if let Some(executable) = provider.executable_name() {
                ui.horizontal(|ui| {
                    ui.label("Executable");
                    ui.monospace(executable);
                });
            } else {
                ui.horizontal(|ui| {
                    ui.label("Executable");
                    ui.text_edit_singleline(&mut self.provider_program);
                });
            }
            ui.horizontal(|ui| {
                ui.label("Additional arguments");
                ui.text_edit_singleline(&mut self.provider_args);
            });
        }
    });
    if self.provider_kind != previous_provider {
        self.provider_status = None;
    }
    if let Some(provider) = self.provider_kind {
        ui.horizontal_wrapped(|ui| {
            if ui
                .add_enabled(!run_active, egui::Button::new("Refresh provider status"))
                .clicked()
            {
                self.provider_status = Some(probe_provider(provider, &self.provider_program));
            }
            if let Some(status) = &self.provider_status {
                ui.label(format!(
                    "Discovery: {} · Auth: {}",
                    if status.discovered {
                        "available"
                    } else {
                        "not found"
                    },
                    status.auth.label()
                ));
            } else {
                ui.weak("Discovery/auth status not probed.");
            }
        });
        let capabilities = provider.capabilities();
        ui.small(format!(
            "Adapter capabilities · structured events: {} · ephemeral MCP: {} · cancellation: {} · provider-managed auth: {}",
            yes_no(capabilities.structured_events),
            yes_no(capabilities.ephemeral_mcp),
            yes_no(capabilities.cancellation),
            yes_no(capabilities.provider_managed_auth),
        ));
        ui.small(
            "Provider credentials remain provider-owned. GameEngine injects only this run's loopback Editor MCP connection into the child process. A first-class provider adapter is not an OS sandbox.",
        );
    } else {
        ui.small(
            "Native local model uses the governed in-process AgentRuntime and the same Agent Host contract.",
        );
    }
    ui.small(
        "All runtimes share the immutable proposal, Agent Host permissions, managed code workspace, validation, Play/frame evidence, and host-owned completion gates.",
    );
    let mut stop_requested = false;
